fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let nx = x.len();
    let ny = y.len();
    let mut grid_x = Vec::with_capacity(ny);
    let mut grid_y = Vec::with_capacity(ny);

    for &yi in &y {
        // each row of grid_x is a copy of x
        grid_x.push(x.clone());
        // each row of grid_y is yi repeated nx times
        grid_y.push(vec![yi; nx]);
    }

    (grid_x, grid_y)
}